import json
from backend.simulation_visual import enhance

def spice_page(project_id):
    return enhance(HTML).replace('__PAYLOAD__',json.dumps({'project_id':project_id},ensure_ascii=False).replace('<','\\u003c'))


HTML='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Simulação elétrica — etapas 13 e 14</title>
<style>body{margin:0;font-family:Arial,sans-serif;background:#f4f6f8;color:#17202a}main{max-width:1100px;margin:auto;padding:24px}h1{margin-bottom:8px}p{line-height:1.5}.bar{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}button,.button{font:inherit;border:0;border-radius:6px;background:#1769aa;color:white;padding:11px 15px;text-decoration:none;cursor:pointer}.secondary{background:#566573}button:disabled{opacity:.45;cursor:default}.card{background:white;border:1px solid #d5dde5;border-radius:8px;padding:20px;margin:18px 0}.status{padding:16px;background:#e7f0f7;border-radius:6px;white-space:pre-wrap;line-height:1.5}.warn{background:#fff3dc}.fields{display:flex;gap:18px;flex-wrap:wrap;align-items:center}label{display:block;line-height:1.5}input,select{font:inherit;padding:8px;border:1px solid #9baaba;border-radius:4px}input[type=text]{width:105px}input[type=range]{width:100%;padding:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}table{width:100%;border-collapse:collapse}th,td{padding:10px;text-align:left;border-bottom:1px solid #e5e7eb}th{background:#f4f6f8}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}li{line-height:1.5;margin:7px 0}[hidden]{display:none!important}@media(max-width:750px){main{padding:14px}.grid{grid-template-columns:1fr}}</style></head>
<body><main><a id="back">Voltar ao fluxo do projeto</a><h1>Simulação elétrica</h1><p>Etapa 13: gerar o arquivo SPICE. Etapa 14: calcular tensões e correntes com ngspice a partir do circuito confirmado.</p>
<div class="bar"><a id="review" class="button secondary">Revisar circuito</a><a id="production" class="button secondary">Esquemático, PCB e ZIP</a><button id="reload" class="secondary">Atualizar tela</button></div><div id="status" class="status" role="status">Carregando...</div>
<div class="card"><h2>Escolha a análise</h2><div class="fields"><label>Análise <select id="analysis"><option value="op">Ponto de operação DC</option><option value="tran">Evolução no tempo</option></select></label><label id="stepLabel" hidden>Passo <input id="step" type="text" value="10u" aria-label="Passo em segundos"></label><label id="stopLabel" hidden>Duração <input id="stop" type="text" value="10m" aria-label="Duração em segundos"></label></div><label id="initialLabel" hidden><input id="initial" type="checkbox" checked> Começar com capacitores descarregados e corrente inicial zero nos indutores.</label><p id="analysisHelp">Calcula o estado estável das fontes DC. Capacitores ficam abertos e indutores ideais se comportam como curto.</p><div class="bar"><button id="generate" disabled>Gerar SPICE — etapa 13</button><button id="simulate" disabled>Simular — etapa 14</button></div><p>Suporte: resistores, capacitores, indutores, fontes DC, baterias, diodos e LEDs. Diodos e LEDs usam modelos genéricos. BJT, MOSFET e AOP usam os parâmetros revisados em Valores e modelos OCR, com aproximações descritas nos avisos. Parâmetros insuficientes impedem a simulação.</p></div>
<div id="result" hidden><div class="card"><h2>Resultados</h2><p id="resultSummary"></p><div id="timeControl" hidden><label id="timeLabel" for="sample">Instante</label><input id="sample" type="range" min="0" value="0" step="1"></div><p>Correntes positivas seguem do primeiro pino indicado para o segundo. Uma fonte fornecendo energia pode apresentar corrente negativa.</p><div class="grid"><div class="scroll"><table><thead><tr><th>Rede</th><th>Tensão (V)</th></tr></thead><tbody id="voltages"></tbody></table></div><div class="scroll"><table><thead><tr><th>Componente</th><th>Sentido</th><th>Corrente (A)</th></tr></thead><tbody id="currents"></tbody></table></div></div></div></div>
<div class="card"><h2>Arquivos e avisos</h2><div class="bar"><a id="cir" class="button secondary" hidden>Baixar simulation.cir</a><a id="csv" class="button secondary" hidden>Baixar resultados CSV</a><a id="json" class="button secondary" hidden>Baixar resultados JSON</a><a id="log" class="button secondary" hidden>Baixar registro</a></div><ul id="warnings"></ul><details><summary>Ver arquivo SPICE</summary><pre id="netlist">Gere a etapa 13 para visualizar.</pre></details></div></main>
<script id="payload" type="application/json">__PAYLOAD__</script><script>
const config=JSON.parse(document.getElementById('payload').textContent),base='/projects/'+encodeURIComponent(config.project_id),el=id=>document.getElementById(id);
let rev=null,confirmed=false,ready=false,busy=false,results=null;
el('back').href=base+'/workflow';el('review').href=base+'/circuit-review-view';el('production').href=base+'/production-view';
function message(text,warn=false){el('status').textContent=text;el('status').className='status'+(warn?' warn':'')}
function controls(){el('generate').disabled=busy||!confirmed;el('simulate').disabled=busy||!confirmed||!ready;el('reload').disabled=busy;for(const name of ['analysis','step','stop','initial'])el(name).disabled=busy}
function analysis(){const tran=el('analysis').value==='tran';for(const name of ['stepLabel','stopLabel','initialLabel'])el(name).hidden=!tran;el('analysisHelp').textContent=tran?'Passo e duração são em segundos: 10u = 10 microssegundos; 10m = 10 milissegundos. Desmarque a condição inicial zero para começar do estado DC estável.':'Calcula o estado estável das fontes DC. Capacitores ficam abertos e indutores ideais se comportam como curto.'}
function options(){return {base_revision:rev,analysis:el('analysis').value,...(el('analysis').value==='tran'?{step:el('step').value,stop:el('stop').value,initial_zero:el('initial').checked}:{})}}
function restoreOptions(opts){if(!opts)return;el('analysis').value=opts.analysis;if(opts.analysis==='tran'){el('step').value=opts.step;el('stop').value=opts.stop;el('initial').checked=!!opts.initial_zero}analysis()}
async function request(url,opts){const r=await fetch(url,opts),data=await r.json();if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'Não foi possível concluir.');return data}
function row(parent,values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=value;tr.appendChild(td)}parent.appendChild(tr)}
function number(value){return Number(value).toLocaleString('pt-BR',{maximumSignificantDigits:7})}
function showSample(){if(!results?.success)return;const index=Number(el('sample').value),sample=results.samples[index];el('voltages').replaceChildren();el('currents').replaceChildren();for(const [name,value] of Object.entries(sample.voltages_v))row(el('voltages'),[name,number(value)]);for(const direction of results.current_directions)row(el('currents'),[direction.component_id,direction.from_pin+' → '+direction.to_pin,number(sample.currents_a[direction.component_id])]);el('timeLabel').textContent='Instante: '+number(sample.time_s||0)+' s — amostra '+(index+1)+' de '+results.point_count}
function showWarnings(items){el('warnings').replaceChildren();for(const text of items||[]){const li=document.createElement('li');li.textContent=text;el('warnings').appendChild(li)}}
function showManifest(manifest){el('cir').hidden=!manifest;el('cir').href=base+'/spice/download';el('netlist').textContent=manifest?.netlist||'Gere a etapa 13 para visualizar.';if(manifest)showWarnings(manifest.warnings)}
function showResults(data){results=data;el('result').hidden=!data?.success;for(const name of ['csv','json','log']){el(name).hidden=!data||(name==='csv'&&!data.success);el(name).href=base+'/simulation/download/'+name}if(data?.success){el('sample').max=data.point_count-1;el('sample').value=data.point_count-1;el('timeControl').hidden=data.options.analysis!=='tran';el('resultSummary').textContent=(data.options.analysis==='op'?'Ponto de operação DC.':'Análise no tempo: '+data.point_count+' amostras.')+' Concluída em '+number(data.elapsed_seconds)+' s.';showSample()}if(data)showWarnings(data.warnings)}
async function load(){const simulator=await request('/simulation/status');ready=simulator.ready;const data=await request(base+'/circuit-review');confirmed=!!data.circuit.confirmed_by_user;rev=data.revision;const manifest=await request(base+'/spice').catch(()=>null),result=await request(base+'/simulation').catch(()=>null);restoreOptions(manifest?.options);showManifest(manifest);showResults(result);message(!confirmed?'Revise e confirme o circuito na etapa 12 para continuar.':!ready?simulator.message:result&&!result.success?result.message:result?.success?'Simulação salva para a versão confirmada atual.':'Circuito confirmado. Gere o SPICE ou execute a simulação.',!confirmed||!ready||!!result&&!result.success);controls()}
async function run(action){busy=true;controls();message(action==='spice'?'Gerando SPICE...':'Simulando com ngspice...');try{const data=await request(base+'/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(options())});if(action==='spice'){showManifest(data);showResults(null);message('Etapa 13 concluída. Arquivo SPICE pronto para simular.')}else{const manifest=await request(base+'/spice');showManifest(manifest);showResults(data);message(data.success?'Etapa 14 concluída. Confira as tensões e correntes.':data.message,!data.success)}}catch(error){message(error.message,true)}finally{busy=false;controls()}}
el('analysis').onchange=analysis;el('sample').oninput=showSample;el('generate').onclick=()=>run('spice');el('simulate').onclick=()=>run('simulation');el('reload').onclick=()=>load().catch(e=>message(e.message,true));analysis();load().catch(e=>{message(e.message+' Abra a revisão do circuito para concluir as etapas anteriores.',true);controls()});
</script></body></html>'''
